BEGIN;INSERT INTO users (full_name, email, password_hash, role) VALUES    ('Proc Seller',  'proc-seller@bidhub.local',  'x', 'SELLER'),    ('Proc Bidder 1','proc-bidder1@bidhub.local', 'x', 'BUYER'),    ('Proc Bidder 2','proc-bidder2@bidhub.local', 'x', 'BUYER');INSERT INTO categories (name, slug) VALUES ('Procedure Test Category', 'proc-test-category');INSERT INTO items (seller_id, category_id, title)SELECT u.user_id, c.category_id, t.titleFROM users u, categories c,     (VALUES        ('Proc Test Item - Active'),        ('Proc Test Item - Closed')     ) AS t(title)WHERE u.email = 'proc-seller@bidhub.local' AND c.slug = 'proc-test-category';INSERT INTO auctions (item_id, starting_price, bid_increment, end_time, status)SELECT item_id, 100.00, 10.00, now() + interval '1 day', 'ACTIVE'FROM items WHERE title = 'Proc Test Item - Active';INSERT INTO auctions (item_id, starting_price, bid_increment, end_time, status)SELECT item_id, 50.00, 5.00, now() - interval '1 hour', 'CLOSED'FROM items WHERE title = 'Proc Test Item - Closed';DO $$DECLARE    v_auction_id  INT;    v_bidder1_id  INT;    v_bid_count   INT;    v_audit_count INT;BEGIN    SELECT a.auction_id INTO v_auction_id    FROM auctions a JOIN items i ON i.item_id = a.item_id    WHERE i.title = 'Proc Test Item - Active';    SELECT user_id INTO v_bidder1_id FROM users WHERE email = 'proc-bidder1@bidhub.local';    CALL place_bid(v_bidder1_id, v_auction_id, 100.00);    SELECT count(*) INTO v_bid_count FROM bids WHERE auction_id = v_auction_id;    SELECT count(*) INTO v_audit_count    FROM audit_log WHERE entity_type = 'auction' AND entity_id = v_auction_id AND action = 'BID_PLACED';    IF v_bid_count = 1 AND v_audit_count = 1 THEN        RAISE NOTICE 'PASS  place_bid accepted the opening bid at starting_price and fired the triggers (1 bid, 1 audit row)';    ELSE        RAISE NOTICE 'FAIL  test_first_bid_at_starting_price: bid_count=% (want 1), audit_count=% (want 1)',            v_bid_count, v_audit_count;    END IF;END $$;DO $$DECLARE    v_auction_id INT;    v_bidder2_id INT;    v_caught     BOOLEAN := false;BEGIN    SELECT a.auction_id INTO v_auction_id    FROM auctions a JOIN items i ON i.item_id = a.item_id    WHERE i.title = 'Proc Test Item - Active';    SELECT user_id INTO v_bidder2_id FROM users WHERE email = 'proc-bidder2@bidhub.local';    BEGIN                CALL place_bid(v_bidder2_id, v_auction_id, 109.99);    EXCEPTION        WHEN SQLSTATE 'AU001' THEN            v_caught := true;    END;    IF v_caught THEN        RAISE NOTICE 'PASS  place_bid rejected an underbid with AU001';    ELSE        RAISE NOTICE 'FAIL  test_underbid_raises_au001: expected AU001, none raised';    END IF;END $$;DO $$DECLARE    v_auction_id INT;    v_seller_id  INT;    v_caught     BOOLEAN := false;BEGIN    SELECT a.auction_id INTO v_auction_id    FROM auctions a JOIN items i ON i.item_id = a.item_id    WHERE i.title = 'Proc Test Item - Active';    SELECT user_id INTO v_seller_id FROM users WHERE email = 'proc-seller@bidhub.local';    BEGIN        CALL place_bid(v_seller_id, v_auction_id, 200.00);    EXCEPTION        WHEN SQLSTATE 'AU003' THEN            v_caught := true;    END;    IF v_caught THEN        RAISE NOTICE 'PASS  place_bid rejected a self-bid with AU003';    ELSE        RAISE NOTICE 'FAIL  test_self_bid_raises_au003: expected AU003, none raised';    END IF;END $$;DO $$DECLARE    v_auction_id INT;    v_bidder1_id INT;    v_caught     BOOLEAN := false;BEGIN    SELECT a.auction_id INTO v_auction_id    FROM auctions a JOIN items i ON i.item_id = a.item_id    WHERE i.title = 'Proc Test Item - Closed';    SELECT user_id INTO v_bidder1_id FROM users WHERE email = 'proc-bidder1@bidhub.local';    BEGIN        CALL place_bid(v_bidder1_id, v_auction_id, 55.00);    EXCEPTION        WHEN SQLSTATE 'AU002' THEN            v_caught := true;    END;    IF v_caught THEN        RAISE NOTICE 'PASS  place_bid rejected a bid on a CLOSED auction with AU002';    ELSE        RAISE NOTICE 'FAIL  test_closed_auction_raises_au002: expected AU002, none raised';    END IF;END $$;DO $$DECLARE    v_bidder1_id INT;    v_caught     BOOLEAN := false;BEGIN    SELECT user_id INTO v_bidder1_id FROM users WHERE email = 'proc-bidder1@bidhub.local';    BEGIN        CALL place_bid(v_bidder1_id, -1, 10.00);    EXCEPTION        WHEN SQLSTATE 'AU004' THEN            v_caught := true;    END;    IF v_caught THEN        RAISE NOTICE 'PASS  place_bid rejected a nonexistent auction with AU004';    ELSE        RAISE NOTICE 'FAIL  test_missing_auction_raises_au004: expected AU004, none raised';    END IF;END $$;DO $$DECLARE    v_seller_id     INT;    v_bidder1_id    INT;    v_bidder2_id    INT;    v_auction_a     INT;    v_auction_b     INT;    v_auction_c     INT;    v_closed_count  INT;    v_live_status   auction_status;    v_txn_count     INT;    v_award_a       INT;    v_award_b       INT;BEGIN    SELECT user_id INTO v_seller_id  FROM users WHERE email = 'proc-seller@bidhub.local';    SELECT user_id INTO v_bidder1_id FROM users WHERE email = 'proc-bidder1@bidhub.local';    SELECT user_id INTO v_bidder2_id FROM users WHERE email = 'proc-bidder2@bidhub.local';    INSERT INTO items (seller_id, category_id, title)    SELECT v_seller_id, c.category_id, t.title    FROM categories c,         (VALUES            ('Cursor Test Item A'),            ('Cursor Test Item B'),            ('Cursor Test Item C')         ) AS t(title)    WHERE c.slug = 'proc-test-category';            INSERT INTO auctions (item_id, starting_price, bid_increment, end_time, status)    SELECT item_id, 100.00, 10.00, now() - interval '1 hour', 'ACTIVE'    FROM items WHERE title = 'Cursor Test Item A'    RETURNING auction_id INTO v_auction_a;    INSERT INTO auctions (item_id, starting_price, bid_increment, end_time, status)    SELECT item_id, 200.00, 20.00, now() - interval '2 hours', 'ACTIVE'    FROM items WHERE title = 'Cursor Test Item B'    RETURNING auction_id INTO v_auction_b;        INSERT INTO auctions (item_id, starting_price, bid_increment, end_time, status)    SELECT item_id, 50.00, 5.00, now() + interval '1 day', 'ACTIVE'    FROM items WHERE title = 'Cursor Test Item C'    RETURNING auction_id INTO v_auction_c;                INSERT INTO bids (auction_id, bidder_id, amount) VALUES (v_auction_a, v_bidder1_id, 120.00);    INSERT INTO bids (auction_id, bidder_id, amount) VALUES (v_auction_a, v_bidder2_id, 130.00);    INSERT INTO bids (auction_id, bidder_id, amount) VALUES (v_auction_b, v_bidder1_id, 250.00);    CALL close_expired_auctions();    SELECT count(*) INTO v_closed_count    FROM auctions    WHERE auction_id IN (v_auction_a, v_auction_b) AND status = 'CLOSED';    SELECT status INTO v_live_status FROM auctions WHERE auction_id = v_auction_c;    SELECT count(*) INTO v_txn_count    FROM transactions    WHERE auction_id IN (v_auction_a, v_auction_b);    SELECT winning_bid_id INTO v_award_a FROM auctions WHERE auction_id = v_auction_a;    SELECT winning_bid_id INTO v_award_b FROM auctions WHERE auction_id = v_auction_b;    IF v_closed_count = 2       AND v_live_status = 'ACTIVE'       AND v_txn_count = 2       AND v_award_a IS NOT NULL       AND v_award_b IS NOT NULL    THEN        RAISE NOTICE 'PASS  close_expired_auctions closed exactly 2 expired auctions, left the live one ACTIVE, wrote 2 transactions, and award_winner populated winning_bid_id on both';    ELSE        RAISE NOTICE 'FAIL  test_close_expired_auctions: closed_count=% (want 2), live_status=% (want ACTIVE), txn_count=% (want 2), award_a=%, award_b=%',            v_closed_count, v_live_status, v_txn_count, v_award_a, v_award_b;    END IF;END $$;ROLLBACK;SELECT 'test_procedures.sql: place_bid validation, trigger side-effects, and cursor-driven batch close all exercised — verify every line above says PASS' AS result;